import{verifyEightSceneMaterial}from'../../world/cargo-eight-scene-geometry.mjs';
import{cargoZoneRow,inCargoZoneFront}from'./zone-registration.mjs';
const readers=new WeakSet();
export function createCargoZoneHostReaders({getConsumer,getMaterial,getWorld,getConsumerWorld,getSessionEpoch,registry}){for(const f of[getConsumer,getMaterial,getWorld,getConsumerWorld,getSessionEpoch])if(typeof f!=='function')throw Error('ZONE_PRIVATE_OWNER_REQUIRED');const out=Object.freeze({readNative(id){const r=cargoZoneRow(id),w=getWorld(),c=getConsumer();if(!r||!w||w!==getConsumerWorld()||!c)return null;const s=c.snapshot(),n=s.native,epoch=getSessionEpoch(),spec=registry.scenes[n?.sceneId],m=getMaterial(n?.sceneId);if(s.active!==true||s.hidden!==false||s.fixturePending!==false||s.uiMode!==null||n?.active!==true||n.pending||n.clock?.paused!==false||n.mapId!=='world:ship:S9'||!Number.isSafeInteger(epoch)||epoch<0||!spec||!verifyEightSceneMaterial(spec,m)||!m.isSafeFoot(n.foot)||!inCargoZoneFront(id,n.sceneId,n.foot,n.facing)||!r.geometryPins.some(p=>p.sha256===m.footMaskSHA256))return null;return{version:1,pointId:id,sceneId:n.sceneId,mapId:'world:ship:S9',observationRevision:r.revision,revision:m.geometryRevision,imageSHA:m.artSHA256,maskSHA:m.footMaskSHA256,foot:[...n.foot],facing:n.facing,sessionEpoch:epoch}}});readers.add(out);return out}
export const isCargoZoneHostReaders=r=>readers.has(r);
